function start(p){return `<section class="final" id="start"><div class="wrap fg"><div><p class="ey">Free site audit</p><h2>Let's fix the page that matters most.</h2><p class="sub">Send your URL. We'll reply within 1 business day with your biggest conversion opportunities.</p><p class="tel">${TEL}</p>${img(p,"team",900,460,"Your team photo","The Beetrix360 team")}</div><form class="fw" data-lead novalidate><div class="wt"><i></i><i></i><i></i><span>beetrix360.com/audit</span></div><div class="fi"><label for="f-w">Website<input id="f-w" name="website" required autocomplete="url"></label><div class="two"><label for="f-n">Name<input id="f-n" name="name" required autocomplete="name"></label><label for="f-e">Work email<input id="f-e" name="email" type="email" required autocomplete="email"></label></div><label for="f-m">What's your main goal?<textarea id="f-m" name="notes" rows="4"></textarea></label><button class="btn pri" type="submit"><span>Get my free audit</span>${ARROW}</button><p class="fmsg" data-msg role="status"></p></div></form></div></section>`}
